input:
/* Input field */
.h5p-advanced-blanks .h5p-text-input {
  min-width: 80px !important;
  max-width: 150px !important;
/* Input field: the library sizes it to the longest correct answer, rounded up
   to the next 10 characters, and from 1.1.2 it grows while the student types.
   Cap it at its row, never at a fixed width: 150px hid most answers. */
.h5p-advanced-blanks .h5p-text-input {
  min-width: 80px !important;
  max-width: 100% !important;

blank:
/* Blank wrapper */
.h5p-advanced-blanks .blank {
  display: inline-block;
  vertical-align: baseline;
}

/* Blank wrapper. max-width: a long field wraps onto its own line and stays
   inside the row, 0.75em short of it so a following . or ? stays beside it. */
.h5p-advanced-blanks .blank {
  display: inline-block;
  vertical-align: baseline;
  max-width: calc(100% - 0.75em);
}

wrapper:
/* Input wrapper */
.h5p-advanced-blanks .h5p-input-wrapper {
  display: inline-block;
  vertical-align: baseline;
  margin: 0 4px;
}

/* Input wrapper */
.h5p-advanced-blanks .h5p-input-wrapper {
  display: inline-block;
  vertical-align: baseline;
  margin: 0 4px;
  max-width: calc(100% - 8px);
}

table-and-narrow:
/* Table layout (used in some Advanced Fill the Blanks variants) */
/* Inside a table cell max-width: 100% does not hold (the cell grows with its
   field), so cap fields there by the frame width instead. */
.h5p-advanced-blanks table .h5p-text-input {
  max-width: 45vw !important;
}

/* Narrow frames (phones): a shown or correct answer is read, not typed, so a
   smaller font lets a long answer fit its row instead of ending in "...".
   Fields being typed in keep their size: under 16px, iOS zooms into them. */
@media (max-width: 480px) {
  .h5p-advanced-blanks .blank.showing-solution .h5p-text-input,
  .h5p-advanced-blanks .blank.correct .h5p-text-input {
    font-size: 14px !important;
  }
}

